using System;
using System.Reflection;
using UnityEngine;
namespace CatCafePreview.Editor
{
    public static class PythonClosingReviewVerification
    {
        static void Check(bool ok,string label){if(!ok)throw new Exception(label);}
        public static void BuildAndVerify()
        {
            PythonClosingSetup.BuildAndVerify();PythonClosingReviewLayout.Build();var preview=UnityEngine.Object.FindObjectOfType<ContentPreview>();preview.Initialize();var client=preview.GetComponent<PythonStateClient>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(PythonStateClient).GetField("preview",flags).SetValue(client,preview);
            var pending=typeof(PythonStateClient).GetField("pending",flags);var state=PythonServiceSetup.Sample();state.instance_id="closing-review";state.day=3;state.closed=true;state.required_action="";state.funds=1050;state.revenue=80;state.finance=new PythonFinanceState{opening_funds=1000,total_income=100,total_expenses=50,net_cash_flow=50,closing_funds=1050};
            state.objective_progress=new PythonObjectiveProgress{label="自由営業",details="期限なし・自由に営業"};state.finance_history=new PythonFinanceHistory{rows=new[]{new PythonFinanceDay{day=2,label="2日目",details="古い収支"},new PythonFinanceDay{day=3,label="3日目",overview="資金 1000 → 1050",details="売上 80 / 支出 50\n前日との差：売上 +20 / 支出 -10 / 収支 +30"}}};state.business_history=new PythonFinanceHistory{rows=new[]{new PythonFinanceDay{day=3,label="3日目",overview="本日の営業成果",details="接客完了 3件\n店舗イベント：街のお祭り"}}};
            Action apply=()=>typeof(PythonStateClient).GetMethod("Accept",flags).Invoke(client,new object[]{state});apply();var panel=preview.GetComponent<PythonClosingPanel>();var review=preview.GetComponent<PythonClosingReview>();string unchanged=JsonUtility.ToJson(state);Check(review.cats.captionText.text==state.cats[0].name && review.cats.captionText.color.r<.5f,"Cat selector label missing");Canvas.ForceUpdateCanvases();Check(review.cats.captionText.preferredHeight<=review.cats.captionText.rectTransform.rect.height,"Cat selector label clipped");
            review.Finance();Check(panel.goalDetails.text.Contains("+20") && !panel.goalDetails.text.Contains("古い収支"),"Wrong comparison day");Capture(preview,"ClosingReviewFinance");review.Business();Check(panel.goalDetails.text.Contains("街のお祭り"),"Daily events missing");Capture(preview,"ClosingReviewBusiness");review.Goal();
            review.SelectCat(2);string selected=state.cats[2].cat_id;review.OpenCat();Check(preview.GetComponent<PythonCatDetailsPanel>().panel.activeSelf,"Cat detail navigation");preview.GetComponent<PythonCatDetailsPanel>().Close();panel.History();Check(preview.GetComponent<PythonFinanceHistoryPanel>().panel.activeSelf,"Finance detail navigation");preview.GetComponent<PythonFinanceHistoryPanel>().Close();Check(JsonUtility.ToJson(state)==unchanged && pending.GetValue(client)==null,"Read only changed state");
            Array.Reverse(state.cats);apply();Check(review.SelectedCatId==selected,"Reorder lost cat");
            var browser=preview.GetComponent<PythonSaveBrowser>();panel.Save();browser.Apply(new PythonSaveList{saves=new PythonSavedGame[0]});Check(browser.panel.activeSelf && pending.GetValue(client)==null,"Save did not open slots");browser.Select(1);browser.Choose();browser.CancelAndRefresh();Check(pending.GetValue(client)==null,"Cancelled save sent command");browser.Choose();browser.Confirm();var command=(PythonShiftCommand)pending.GetValue(client);Check(command?.kind=="save_game" && command.save_slot==2 && !panel.next.interactable,"Save slot or busy guard");pending.SetValue(client,null);apply();browser.Close();
            state.required_action="帰還を確認してください。";apply();Check(!panel.next.interactable && panel.notice.text.Contains("帰還"),"Required guard");state.required_action="";state.pending_results=new PythonPendingResults{count=1};apply();preview.GetComponent<PythonPersistPanel>().Close();Check(!panel.save.interactable && !panel.next.interactable && panel.notice.text.Contains("未保存"),"Pending results guidance");state.pending_results=null;
            typeof(PythonStateClient).GetField("online",flags).SetValue(client,false);panel.Disconnect();Check(!panel.next.interactable && !review.catDetails.interactable && panel.notice.text.Contains("未接続"),"Offline controls");apply();
            state.business_history.rows[0].details=new string('猫',3000);apply();review.Business();Canvas.ForceUpdateCanvases();Check(panel.goalScroll.content.rect.height>panel.goalScroll.viewport.rect.height,"Long events cannot scroll");review.Goal();Capture(preview,"ClosingReviewOrganized");
            state.autoplay=new PythonAutoPlay{running=true};apply();panel.Open();Check(!panel.panel.activeSelf,"Review covered autoplay");state.autoplay=null;apply();panel.Next();Check(((PythonShiftCommand)pending.GetValue(client))?.kind=="next_day","Next day command");pending.SetValue(client,null);state.closed=false;state.can_set_shifts=true;state.day++;apply();Check(!panel.panel.activeSelf && preview.GetComponent<PythonPreparationPanel>().panel.activeSelf,"Next preparation missing");
            Debug.Log("CAT_CAFE_CLOSING_REVIEW_VERIFIED: comparison / daily events / goal / cat details / finance details / read only / reordered cats / slot save / cancel / busy / required / persist / offline / long text / autoplay / next preparation");
        }
        static void Capture(ContentPreview p,string name){Canvas.ForceUpdateCanvases();typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{p,"Logs/"+name+".png"});}
    }
}
